Olá! Fico feliz em ajudar você a criar este bot no Telegram usando Node.js e Telegraf. Este é um caso de uso perfeito para gerenciar estados e usar `setInterval` para a contagem regressiva.

Abaixo está um código completo, detalhado e comentado que implementa essa funcionalidade.

### Pré-requisitos

Antes de rodar o código, certifique-se de ter:

1.  **Node.js** instalado.
2.  Um **Token do Bot** obtido do BotFather no Telegram.
3.  Um projeto Node.js inicializado (`npm init`).
4.  As dependências instaladas: `npm install telegraf`

### Código (`bot.js`)

```javascript
const { Telegraf } = require('telegraf');

// ⚠️ SUBSTITUA PELO SEU TOKEN REAL DO TELEGRAM ⚠️
const BOT_TOKEN = 'SEU_TOKEN_DO_BOT_AQUI';
const bot = new Telegraf(BOT_TOKEN);

// Estrutura para armazenar os timers e os dados de contagem regressiva por usuário
// { chatId: { totalMs: 0, intervalId: null, startTime: Date } }
const countdowns = new Map();

/**
 * Converte uma string de tempo "HH:MM" para milissegundos.
 * @param {string} timeStr - Ex: "02:00"
 * @returns {number} Tempo total em milissegundos.
 */
function timeToMilliseconds(timeStr) {
    const [hoursStr, minutesStr] = timeStr.split(':');
    const hours = parseInt(hoursStr) || 0;
    const minutes = parseInt(minutesStr) || 0;
    return (hours * 60 * 60 * 1000) + (minutes * 60 * 1000);
}

/**
 * Inicia a contagem regressiva para um chatId específico.
 * @param {number} chatId - O ID do chat do usuário.
 * @param {number} totalMs - O tempo total em milissegundos.
 */
function startCountdown(chatId, totalMs) {
    // 1. Limpar qualquer timer anterior para evitar duplicidade
    if (countdowns.has(chatId) && countdowns.get(chatId).intervalId) {
        clearInterval(countdowns.get(chatId).intervalId);
    }

    // 2. Registrar o estado
    countdowns.set(chatId, {
        totalMs: totalMs,
        startTime: Date.now(),
        intervalId: null,
    });

    const intervalMs = 30 * 60 * 1000; // 30 minutos

    console.log(`[INFO] Contagem iniciada para Chat ${chatId} com ${totalMs / 1000 / 60} minutos.`);

    // 3. Configurar o intervalo
    const interval = setInterval(() => {
        const state = countdowns.get(chatId);
        if (!state) return; // Garante que o estado ainda existe

        const elapsedTime = Date.now() - state.startTime;
        let remainingMs = state.totalMs - elapsedTime;

        if (remainingMs <= 0) {
            // Fim da contagem
            clearInterval(interval);
            countdowns.delete(chatId);
            bot.telegram.sendMessage(chatId, "⏰ **Tempo esgotado!** A contagem regressiva terminou.");
            console.log(`[FIM] Contagem finalizada para Chat ${chatId}.`);
            return;
        }

        // Converter milissegundos restantes para HH:MM
        const totalSeconds = Math.floor(remainingMs / 1000);
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);

        // Formatação para garantir 2 dígitos (ex: 02 em vez de 2)
        const formattedTime = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;

        // Enviar a mensagem
        bot.telegram.sendMessage(chatId, `⏳ **Tempo restante:** ${formattedTime}`);
    }, intervalMs);

    // 4. Atualizar o estado com o ID do intervalo
    countdowns.get(chatId).intervalId = interval;
}


// --- HANDLERS DO BOT ---

// Comando /start: Instruções ao usuário
bot.start(ctx => {
    ctx.reply(
        "👋 Olá! Eu sou seu contador regressivo.\n" +
        "Para iniciar, por favor, envie o tempo desejado no formato **HH:MM** (ex: 02:00 para 2 horas).\n" +
        "⚠️ As notificações serão enviadas a cada 30 minutos."
    );
});

// Listener de mensagens de texto
bot.on('text', async (ctx) => {
    const text = ctx.message.text.trim();
    const chatId = ctx.chat.id;

    // 1. Verifica se o usuário já está em uma contagem ativa
    if (countdowns.has(chatId)) {
        return ctx.reply("🔔 Você já tem uma contagem regressiva ativa. Aguarde o tempo acabar ou use /cancel para parar.");
    }

    // 2. Valida o formato HH:MM
    const timeRegex = /^(\d{1,2}):(\d{1,2})$/;
    const match = text.match(timeRegex);

    if (!match) {
        return ctx.reply("❌ Formato inválido. Por favor, use **HH:MM** (Ex: 02:00).");
    }

    // 3. Valida se os minutos são menores que 60
    const minutes = parseInt(match[2]);
    if (minutes >= 60) {
        return ctx.reply("❌ Os minutos não podem ser 60 ou mais.");
    }

    // 4. Converte e inicia
    try {
        const totalMs = timeToMilliseconds(text);
        startCountdown(chatId, totalMs);

        ctx.reply(
            `✅ Contagem iniciada com sucesso! ⏳\n` +
            `Tempo total: ${text}.\n` +
            `Você receberá um aviso a cada 30 minutos.`
        );

    } catch (error) {
        console.error("Erro ao iniciar contagem:", error);
        ctx.reply("⚠️ Ocorreu um erro ao processar o tempo. Tente novamente.");
    }
});

// Comando /cancel: Para a contagem regressiva
bot.command('cancel', (ctx) => {
    const chatId = ctx.chat.id;

    if (countdowns.has(chatId)) {
        const state = countdowns.get(chatId);
        clearInterval(state.intervalId);
        countdowns.delete(chatId);

        ctx.reply("🛑 Contagem regressiva cancelada com sucesso! Se precisar de outro, basta enviar um novo tempo HH:MM.");
    } else {
        ctx.reply("ℹ️ Você não tem nenhuma contagem regressiva ativa para cancelar.");
    }
});


// --- INICIALIZAÇÃO ---
bot.launch();
console.log('🚀 Bot do Telegram está rodando! Pressione Ctrl+C para parar.');

// Garante que os timers sejam limpos se o processo for encerrado
process.on('SIGINT', () => {
    console.log('\n🛑 Encerrando o bot...');
    // Limpar todos os intervalos ativos
    countdowns.forEach((state, chatId) => {
        clearInterval(state.intervalId);
        console.log(`[LIMPO] Timer do Chat ${chatId} encerrado.`);
    });
    bot.stop('SIGINT');
    process.exit(0);
});
```

### Como Executar

1.  Substitua `'SEU_TOKEN_DO_BOT_AQUI'` pelo seu token real.
2.  Execute no terminal: `node bot.js`
3.  Abra o Telegram, encontre seu bot e use `/start` para ver as instruções.
4.  Envie, por exemplo: `02:00`
5.  O bot confirmará e começará a enviar mensagens a cada 30 minutos informando o tempo restante (ex: `01:00`, `00:00`).
6.  Para parar a contagem a qualquer momento, use `/cancel`.

### Detalhamento Técnico

1.  **`countdowns` (Map):** Usamos um `Map` em vez de um objeto simples para mapear `chatId` (chave) para o estado da contagem (valor). Isso é crucial porque o estado precisa ser **por usuário**, e cada usuário tem seu próprio *timer*.
2.  **`timeToMilliseconds`:** Conversão padronizada de `HH:MM` para milissegundos, que é a unidade nativa do JavaScript para `Date` e `setInterval`.
3.  **`startCountdown`:** Esta função é o coração. Ela **limpa timers antigos** (prevenindo que o bot envie mensagens múltiplas se o usuário enviar o mesmo tempo duas vezes) e usa `setInterval` configurado para **30 minutos** (`30 * 60 * 1000`).
4.  **Lógica de Tempo:** Dentro do intervalo, calculamos `tempo_decorrido = Date.now() - startTime`. O tempo restante é `totalMs - tempo_decorrido`.
5.  **Formatação:** Usamos `String().padStart(2, '0')` para garantir que o formato de saída seja sempre `HH:MM` (ex: `01:05` em vez de `1:5`).
6.  **Limpeza:** Implementamos o `process.on('SIGINT')` para garantir que, ao parar o script (`Ctrl+C`), **todos os timers ativos sejam limpos** (`clearInterval`), prevenindo vazamentos de memória ou mensagens indesejadas no futuro.

Espero que este código seja exatamente o que você precisava! Se tiver qualquer dúvida sobre como modificar, otimizar ou implementar outras funcionalidades, é só perguntar! 😊

